REQUEST
# Batch operation contract

Implement `processBatch(items)` and wire `runBatchCommand(payload)` to it.

- Return one result for every input item in the original order.
- A successful entry is `{ ok: true, value }`.
- A failed entry is `{ ok: false, error }` and must not stop later items.
- Empty input returns an empty result list.
- `runBatchCommand({ items })` returns `{ results }`.
- Do not change `processItem`, its exported name, or its exact error messages.

SERVICE
export function processItem(item) {
  if (typeof item?.id !== 'string' || item.id.length === 0) {
    throw new Error('Item id is required.');
  }
  if (item.fail === true) {
    throw new Error(`Item ${item.id} failed.`);
  }
  return { id: item.id, value: String(item.value ?? '').trim() };
}

export function processBatch(_items) {
  throw new Error('Batch operation is not implemented.');
}

ADAPTER
import { processItem } from './item-service.mjs';

export function runBatchCommand(payload) {
  return { results: payload.items.map(processItem) };
}

TEST
import test from 'node:test';
import assert from 'node:assert/strict';

import { runBatchCommand } from '../src/command-adapter.mjs';
import { processBatch } from '../src/item-service.mjs';

test('keeps successful and failed results in input order', () => {
  const items = [
    { id: 'a', value: ' first ' },
    { id: 'b', fail: true },
    { id: 'c', value: 'third' },
  ];
  assert.deepEqual(processBatch(items), [
    { ok: true, value: { id: 'a', value: 'first' } },
    { ok: false, error: 'Item b failed.' },
    { ok: true, value: { id: 'c', value: 'third' } },
  ]);
});

test('command adapter returns the batch result contract', () => {
  assert.deepEqual(runBatchCommand({ items: [] }), { results: [] });
});

